+fn verify_finish(facets: &[Triangle], t: &Toolpath) -> Vec<Warning> {
+    verify_at(facets, t, TOP)
+}
+
+fn verify_at(facets: &[Triangle], t: &Toolpath, stock_top: f64) -> Vec<Warning> {
+    let region: Region = slice::project(facets, 64).expect("fixture silhouette");
+    let tool = ToolGeom {
+        radius: R,
+        nose_radius: 0.0,
+        flute_len: 10.0,
+        shank_radius: 2.9,
+        shank_len: 40.0,
+        holder_radius: 4.9,
+        holder_len: 30.0,
+    };
+    let cx = VerifyContext {
+        region: &region,
+        stock: None,
+        model: Some(facets),
+        tool: &tool,
+        cutter: None,
+        mode: Mode::Envelope,
+        stock_top_z: stock_top,
+        clearance_z: 25.0,
+        stock_to_leave: 0.0,
+        gouge_tol: 0.01,
+        z_tol: 1e-6,
+        finish_tol: Some(TOL),
+        fixtures: &[],
+        spindle: None,
+        ..Default::default()
+    };
+    verify(t, &cx).into_iter().filter(|w| w.blocks_post()).collect()
+}
